head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDSTF07302";
scwin.vBzProcsNo = "";
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.dts_ReqInf = null;
scwin.dts_Cmt = null;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.dts_ReqInf = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ReqInf')) : $c.util.getComponent('dts_ReqInf');
        scwin.dts_Cmt = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Cmt')) : $c.util.getComponent('dts_Cmt');
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07302.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.Provider
    try {
        const arr = [];
        const parentWin = $c.win.getParent();
        fn_GetPar = parentWin.fn_GetPar;
        fn_SetPar = parentWin.fn_SetPar;
        if (fn_GetPar != null) {
            fn_GetPar(arr);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_GetPar — as-is 공통(폼 전역 의존) — 반입 보류
        }
        $c.util.getComponent("ipt_txb_IsurCd").setValue((arr.length >= 1 ? arr[0] : ""));
        $c.util.getComponent("ipt_txb_CoNm").setValue((arr.length >= 3 ? arr[2] : ""));
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        await scwin.searchWebRflct();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07302.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Cmt_onloadcompleted
 * @description dts_Cmt onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Cmt_onloadcompleted = async function (rowcount) {
    try {
        // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
        if (scwin.dts_Cmt.CountRow > 0) {
            fn_setKeyCtrOnUpd();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_setKeyCtrOnUpd — as-is 공통(폼 전역 의존) — 반입 보류
            fn_searchReqInf();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_searchReqInf — as-is 공통(폼 전역 의존) — 반입 보류
            fn_read();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_read — as-is 공통(폼 전역 의존) — 반입 보류
        } else {
            if (await $c.win.confirm(MSG_NO_COMT)) {
                fn_addNewCmt();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_addNewCmt — as-is 공통(폼 전역 의존) — 반입 보류
            } else {
                $c.win.closePopup();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07302.dts_Cmt_onloadcompleted" });
    }
};

/**
 * @method
 * @name dts_Cmt_onrowposchanged
 * @description dts_Cmt onrowposchanged 이벤트
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_Cmt_onrowposchanged = function (row) {
    try {
        if (scwin.dts_Cmt.CountRow > 0) {
            if (scwin.dts_Cmt.getCellData(row, "BZ_PROCS_NO") !== "") {
                fn_searchReqInf();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_searchReqInf — as-is 공통(폼 전역 의존) — 반입 보류
            }
            fn_read();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_read — as-is 공통(폼 전역 의존) — 반입 보류
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07302.dts_Cmt_onrowposchanged" });
    }
};

/**
 * @method
 * @name dts_ReqInf_onloadcompleted
 * @description dts_ReqInf onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReqInf_onloadcompleted = function (rowcount) {
    try {
        $c.util.getComponent('ipt_med_LIST_DELIB_SCHDL_DD').setSelectionValue(0, 8, scwin.dts_ReqInf.getCellData(1, "LIST_DELIB_SCHDL_DD"));
        $c.util.getComponent('ipt_med_INVSTG_DTL_WEB_DP_DD').setSelectionValue(0, 8, scwin.dts_ReqInf.getCellData(1, "INVSTG_DTL_WEB_DP_DD"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07302.dts_ReqInf_onloadcompleted" });
    }
};

/**
 * @method
 * @name tr_Save_onfail
 * @description 알림을 띄운다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Save_onfail = async function () {
    try {
        await $c.win.alert(scwin.MSG_TR_FAIL);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07302.tr_Save_onfail" });
    }
};

/**
 * @method
 * @name tr_Save_onsuccess
 * @description 알림을 띄운다 외
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Save_onsuccess = async function () {
    try {
        // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
        await $c.win.alert(scwin.MSG_TR_DOME);
        scwin.parentRefresh();
        $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07302.tr_Save_onsuccess" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07302.btn_Close_onclick' }); }
};

/**
 * @method
 * @name img_Save_onclick
 * @description img_Save 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Save_onclick = async function () {
    try {
        await scwin.sbm_tr_Save("I");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07302.img_Save_onclick' }); }
};

/**
 * @method
 * @name img_SetInvstgDtlWebDpDd_onclick
 * @description img_SetInvstgDtlWebDpDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SetInvstgDtlWebDpDd_onclick = function () {
    try {
        scwin.showCalendar(ipt_med_INVSTG_DTL_WEB_DP_DD);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07302.img_SetInvstgDtlWebDpDd_onclick' }); }
};

/**
 * @method
 * @name img_SetListDelibSchdlDd_onclick
 * @description img_SetListDelibSchdlDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SetListDelibSchdlDd_onclick = function () {
    try {
        scwin.showCalendar(ipt_med_LIST_DELIB_SCHDL_DD);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07302.img_SetListDelibSchdlDd_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_ReqInf
 * @description script dts Req Inf 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_ReqInf = async function () {
    $c.util.getComponent("dma_scriptDts_ReqInfReq").set("SCREN_ID", "ULDSTF07302.gfm");
    $c.util.getComponent("dma_scriptDts_ReqInfReq").set("BZ_PROCS_NO", "");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD", unresolved: "query_param:SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_ReqInf",
        method: "post",
        action: "/konex/PrelmInvstgKonex.do",
        ref: "dma_scriptDts_ReqInfReq",
        target: "dts_ReqInf=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_ReqInf_onloaderror'] === 'function') ? scwin['dts_ReqInf_onloaderror'] : (typeof scwin['dts_ReqInf_onfail'] === 'function') ? scwin['dts_ReqInf_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_ReqInf_onloadcompleted'] === 'function') ? scwin['dts_ReqInf_onloadcompleted'] : ((typeof scwin['dts_ReqInf_onsuccess'] === 'function') ? scwin['dts_ReqInf_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_ReqInf'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07302.tx_script_dts_ReqInf" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name sbm_tr_Save
 * @description tr Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_tr_Save = async function () {
    const sbmOptions = {
        id: "sbm_tr_Save",
        method: "post",
        action: "/konex/PrelmInvstgKonex.do",
        ref: "dma_sbmTr_SaveReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name showCalendar
 * @description show Calendar 처리
 * @param {*} o o
 * @returns {void}
 * @hidden N
 */
scwin.showCalendar = function (o) {
    if ((o != null) && (!o.readOnly)) {
        popUpCalendar2(o);
    }
};

/**
 * @method
 * @name getUserId
 * @description get User Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getUserId = function () {
    return $c.session.getUserInfo("empNo");
};

/**
 * @method
 * @name searchWebRflct
 * @description search Web Rflct 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchWebRflct = async function () {
    let uri = "/konex/PrelmInvstgKonex.do?SCREN_ID=" + "ULDSTF07302.gfm" + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_01 + "&method=readWebRflct";
    uri += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;

    await scwin.tx_script_dts_ReqInf();
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.Provider
    const fr_fn_list_sync = $c.win.getParent().fn_list_sync;
    fr_fn_list_sync();
};
// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
